import { request } from '../utils/request';

export function fetchMyAlbum() {
	return request({ url: '/api/users/me/album' });
}

export function addAlbumPhotos(photos) {
	return request({
		url: '/api/users/me/album/photos',
		method: 'POST',
		data: { photos }
	});
}

export function deleteAlbumPhoto(id) {
	return request({
		url: `/api/users/me/album/photos/${encodeURIComponent(id || '')}`,
		method: 'DELETE'
	});
}

export function updateAlbumOrder(itemKeys) {
	return request({
		url: '/api/users/me/album/order',
		method: 'PUT',
		data: { itemKeys }
	});
}
